// FailedItems 失败的项（项的标识在 Key 中）；全部成功时为 nil。
func (v *BatchDecideResult) FailedItems() []ItemError {
	var out []ItemError
	for _, item := range v.Results {
		if item.Error != nil {
			out = append(out, *item.Error)
		}
	}
	return out
}

// OK 全部成功。
func (v *BatchDecideResult) OK() bool { return len(v.FailedItems()) == 0 }

// Err 有失败的项时返回汇总的错误（*BatchError），全部成功时为 nil。
func (v *BatchDecideResult) Err() error {
	return batchErr(v.FailedItems())
}

