// AddWordsResult 添加词条的结果
type AddWordsResult struct {
	// 新增的个数
	Added int64 `json:"added"`
	// 已存在的词条（原样）
	Duplicated []string    `json:"duplicated"`
	Invalid    []ItemError `json:"invalid"`
	// Raw 服务端返回的这个对象的原始 JSON；服务端新增的字段可以从中读取。
	Raw json.RawMessage `json:"-"`
}

// UnmarshalJSON 解码并保存原始 JSON。
func (v *AddWordsResult) UnmarshalJSON(b []byte) error {
	type plain AddWordsResult
	if err := json.Unmarshal(b, (*plain)(v)); err != nil {
		return err
	}
	var keys struct {
		Items []struct {
			Key  string `json:"word"`
			Code string `json:"reason"`
		} `json:"invalid"`
	}
	if err := json.Unmarshal(b, &keys); err != nil {
		return err
	}
	for i := range v.Invalid {
		if i < len(keys.Items) {
			v.Invalid[i].Key = keys.Items[i].Key
			v.Invalid[i].Code = keys.Items[i].Code
		}
	}
	v.Raw = cloneRaw(b)
	return nil
}

// FailedItems 失败的项（项的标识在 Key 中）；全部成功时为 nil。
func (v *AddWordsResult) FailedItems() []ItemError {
	if len(v.Invalid) == 0 {
		return nil
	}
	return append([]ItemError(nil), v.Invalid...)
}

// OK 全部成功。
func (v *AddWordsResult) OK() bool { return len(v.FailedItems()) == 0 }

// Err 有失败的项时返回汇总的错误（*BatchError），全部成功时为 nil。
func (v *AddWordsResult) Err() error {
	return batchErr(v.FailedItems())
}

