func encAIUsage(w *jw, v AIUsage) {
	w.beginObject()
	w.key("input_tokens")
	encInt64(w, v.InputTokens)
	w.key("output_tokens")
	encInt64(w, v.OutputTokens)
	w.endObject()
}

func encAIPart(w *jw, v AIPart) {
	w.beginObject()
	w.key("type")
	encStr(w, v.Type)
	if v.Text != "" {
		w.key("text")
		encStr(w, v.Text)
	}
	if v.URL != "" {
		w.key("url")
		encStr(w, v.URL)
	}
	if v.Width != 0 {
		w.key("width")
		encInt64(w, v.Width)
	}
	if v.Height != 0 {
		w.key("height")
		encInt64(w, v.Height)
	}
	if v.Alt != "" {
		w.key("alt")
		encStr(w, v.Alt)
	}
	if v.Name != "" {
		w.key("name")
		encStr(w, v.Name)
	}
	if v.Size != 0 {
		w.key("size")
		encInt64(w, v.Size)
	}
	if v.MimeType != "" {
		w.key("mime_type")
		encStr(w, v.MimeType)
	}
	if v.ID != "" {
		w.key("id")
		encStr(w, v.ID)
	}
	if v.Title != "" {
		w.key("title")
		encStr(w, v.Title)
	}
	if v.State != "" {
		w.key("state")
		encStr(w, v.State)
	}
	w.endObject()
}

func encPenaltyRule(w *jw, v PenaltyRule) {
	w.beginObject()
	w.key("window_hours")
	encInt64(w, v.WindowHours)
	w.key("threshold")
	encInt64(w, v.Threshold)
	if v.Categories != nil {
		w.key("categories")
		encSlice(encStr)(w, v.Categories)
	}
	w.key("action")
	encStr(w, v.Action)
	if v.MuteScopes != nil {
		w.key("mute_scopes")
		encSlice(encStr)(w, v.MuteScopes)
	}
	if v.DurationSeconds != nil {
		w.key("duration_seconds")
		encInt64(w, *v.DurationSeconds)
	}
	w.endObject()
}
